%[text] ## Demo4: Iterative Learning Control Experiment
%%
%[text] ### STEP 1: DESIGN FEEDBACK CONTROLLER
%[text] load settings for the experiment
clear; close all;

omega = 15; % desired pole [rad/s], not [Hz]
Smax = 2; % maximum gain of sensitivity function, 6 dB

cfg = experiment.ExperimentConfig.defaults();
plant_mat_path = fullfile(experiment.scenario.default_result_dir(), "plant.mat");
plant_data = experiment.exp0n.load_plant_data( ...
  plant_mat_path, "expected_sample_time_s", 1 / cfg.env.task_rate_hz);
Pd = plant_data.Pd;
Pdn = plant_data.Pdn;
Jn = plant_data.Jn;
Dn = plant_data.Dn;
Ts = plant_data.Ts;
%%
%[text] design FB controller
%[text] (hint: during tuning of FF input the designed FB controller in demo2 may not be optimal)
Kpid = experiment.exp02.designpid(Dn/Jn, 0, 1/Jn, omega);
Kd = c2d(Kpid, Ts, "tustin"); % digital feedback controller
% load(fullfile(experiment.scenario.default_result_dir(), "feedback_result.mat"), "Kd"); % reuse Demo2 controller
%%
%[text] ### Check the stability and performance of FB Controller (Always check before experiment!!!)
%[text] use nyquist and sensitivity plot
%[text] (note: Pd is actual system, Pdn is modelled system)
stability = experiment.exp02.stability_check( ... %[output:group:050b15e0] %[output:8b1e8228] %[output:783c7daa]
  Pd, Pdn, Kd, Smax, ... %[output:8b1e8228] %[output:783c7daa]
  "error_id", "experiment:exp04_ilc:sensitivityLimitExceeded"); %[output:group:050b15e0] %[output:8b1e8228] %[output:783c7daa]
stability_summary = table( ...
  stability.max_sensitivity, Smax, stability.limit_exceeded, ...
  VariableNames=["measuredSensitivityPeak", "limit", "limitExceeded"]);
display(stability_summary); %[output:685ba26d]
%%
%[text] ### STEP 2: ILC EXPERIMENT
%[text] configure ILC operation conditions
Ntrial = 10; % number of learning trials [int]
alpha = 0.6; % Temp reference learning gain (0<a<=1)
q_cutoff_hz = 120; % below the 200 Hz VM torsional mode; short enough for the 25 ms splice
noQ = false; % option of not using the robustness (Q) filter
maxInput = 1.6; % maximum control input [A]
Npad = 100; % padding samples used by srinv/filtfilt_clean
transient_samples = 200; % 25 ms transient splice length at 8 kHz
settling_tail_s = 9.0; % leaves the VM at an exact zero-velocity trial boundary

hold_margin_s = 1.0;
save_results = true;
%%
%[text] ### Design Learning filter and Robustness (Q) filter of ILC
%[text] **\*\*\*LEARNING WILL DIVERGE IF |Q|^2|1-JL| \> 1 FOR ANY FREQUENCY\*\*\***
%[text] (hint: typically Q filter is designed as a low-pass filter)
trajectory = experiment.exp0n.load_trajectory( ...
  "expected_sample_time_s", Ts, "table_max_n", cfg.env.table_max_n);
scenario = experiment.scenario.exp04( ...
  plant_data, trajectory, "cfg", cfg, "omega", omega, "Smax", Smax, ...
  "Kd", Kd, "trial_count", Ntrial, "alpha", alpha, ...
  "q_cutoff_hz", q_cutoff_hz, "noQ", noQ, ...
  "max_input_A", maxInput, "Npad", Npad, ...
  "transient_samples", transient_samples, ...
  "settling_tail_s", settling_tail_s, ...
  "hold_margin_s", hold_margin_s, "save_results", save_results);
trajectory = scenario.trajectory;
learning_filters = scenario.learning_filters;
learning_summary = table( ...
  learning_filters.max_convergence_gain, q_cutoff_hz, alpha, ...
  learning_filters.max_convergence_gain < 1, ...
  VariableNames=["convergencePeak", "qCutoff_Hz", ...
    "learningGain", "convergenceSatisfied"]);
display(learning_summary); %[output:9f4654b1]

figure; %[output:3c38afd7]
bop = bodeoptions("cstprefs");
bop.FreqUnits = "Hz";
bop.XLimMode = "manual";
bop.XLim = {[1, 1/2/Ts]};
bop.Grid = "off";
bodemag(learning_filters.convergence_condition, bop); hold on; %[output:3c38afd7]
plot([1, 1/2/Ts], [0, 0], "Color", "black", "LineStyle", "--"); hold off; %[output:3c38afd7]
title("Convergence condition of ILC"); %[output:3c38afd7]
%%
%[text] initialize storage variables
t = trajectory.t;
r = trajectory.p;

figure; %[output:15e699fa]
plot(t, r, "b"); %[output:15e699fa]
grid off; %[output:15e699fa]
xlabel("Time [s]"); ylabel("Position [rad]"); %[output:15e699fa]

%%
%[text] execute the ten-trial VirtualMotor campaign through the shared workflow
%[text] The same dashboard is refreshed after each completed trial; no trial image files are written.
workflow = experiment.workflow.run_exp04( ...
  scenario, "dashboard_visibility", "auto");
history = workflow.history;
completed_trials = history.completedTrials;
trial_summary = history.trialSummary;
display(trial_summary); %[output:740c4594]
campaign_summary = table( ...
  workflow.metrics.completed_trials, workflow.metrics.best_trial, ...
  workflow.metrics.best_error_norm, workflow.metrics.monotonic_decrease, ...
  workflow.metrics.max_abs_feedforward_A, ...
  workflow.metrics.max_abs_total_input_A, ...
  VariableNames=["completedTrials", "bestTrial", "bestErrorNorm", ...
    "monotonicDecrease", "maxFeedforward_A", "maxTotalInput_A"]);
display(campaign_summary); %[output:58f020b1]
%%
%[text] save experiment data
completed_at_utc = string(datetime("now", "TimeZone", "UTC", ...
  "Format", "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"));
artifact_summary = table( ...
  workflow.artifacts.saved, string(workflow.artifacts.run_directory), ...
  string(workflow.artifacts.result), completed_at_utc, ...
  VariableNames=["saved", "runDirectory", "ilcResult", "completedAtUtc"]);
display(artifact_summary); %[output:29827f54]
%%
%[text] ### STEP 3: Analyze the results of the experiment
%[text] download data
%%
%[text] plot tracking result of ILC
j = history.bestTrial; % choose the best completed iteration

figure; %[output:03850586]
subplot(3, 1, 1); %[output:03850586]
plot(t, history.r(:, j), t, history.y(:, j)); %[output:03850586]
xlabel("Time [s]"); ylabel("Position [rad]"); %[output:03850586]
grid on; %[output:03850586]

subplot(3, 1, 2); %[output:03850586]
plot(t, history.e(:, j)); %[output:03850586]
xlabel("Time [s]"); ylabel("Tracking error [rad]"); %[output:03850586]
grid on; %[output:03850586]

subplot(3, 1, 3); %[output:03850586]
plot(t, history.ffApplied(:, j)); hold on; ... %[output:03850586]
plot(t, history.u(:, j)-history.ffApplied(:, j)); hold off; %[output:03850586]
xlabel("Time [s]"); ylabel("Input [A]"); %[output:03850586]
legend("FF", "FB"); %[output:03850586]
grid on; %[output:03850586]
sgtitle(string(j) + " th iteration result"); %[output:03850586]
%%
%[text] plot transition of error norm
figure; %[output:6d2d82c1]
semilogy(1:completed_trials, history.eNorm, "-o"); hold on; %[output:6d2d82c1]
grid on; %[output:6d2d82c1]
xlabel("Iteration"); ylabel("$\|e\|_2$", "Interpreter", "latex"); %[output:6d2d82c1]
title("Position error"); %[output:6d2d82c1]
%%
%[text] smallest 2 norm error in iteration
best_trial_summary = table( ...
  history.bestTrial, history.bestErrorNorm, ...
  VariableNames=["bestTrial", "bestErrorNorm"]);
display(best_trial_summary); %[output:25839871]


